import app from "flarum/forum/app";
import Modal from "flarum/common/components/Modal";
import Button from "flarum/common/components/Button";
import getBadgeSvg from "../../common/utils/getBadgeSvg";
/**
 * Modal de celebração mostrado uma única vez quando o usuário acaba de
 * ser verificado. Em `hide()` persiste o stamp da verificação atual
 * (`verifiedAt`) na preferência server-side
 * `ramonVerifiedCelebrationShownAt` — assim uma re-verificação no futuro
 * reabre o modal exatamente uma vez.
 */
export default class VerifiedCelebrationModal extends Modal {
  persisted = false;
  className() {
    return "VerifiedRequestModal VerifiedCelebrationModal Modal--medium";
  }
  title() {
    return app.translator.trans("ramon-verified.forum.verified_celebration.title");
  }
  content() {
    return m("div", {
      className: "Modal-body VerifiedRequestModal-body"
    }, m("div", {
      className: "VerifiedRequestModal-hero"
    }, m("div", {
      className: "VerifiedRequestModal-hero-icon",
      "aria-hidden": "true"
    }, m("span", {
      className: "VerifiedRequestModal-hero-iconBadge"
    }, m.trust(getBadgeSvg()))), m("h2", {
      className: "VerifiedRequestModal-hero-title"
    }, app.translator.trans("ramon-verified.forum.verified_celebration.title")), m("p", {
      className: "VerifiedRequestModal-hero-text"
    }, app.translator.trans("ramon-verified.forum.verified_celebration.body"))), m("div", {
      className: "VerifiedRequestModal-footer"
    }, m(Button, {
      className: "Button Button--primary",
      onclick: () => this.hide()
    }, app.translator.trans("ramon-verified.forum.verified_celebration.ok_button"))));
  }
  hide() {
    this.persistShown();
    super.hide();
  }
  persistShown() {
    if (this.persisted) return;
    this.persisted = true;
    const user = app.session && app.session.user;
    if (!user || !user.savePreferences) return;
    try {
      user.savePreferences({
        ramonVerifiedCelebrationShownAt: this.attrs.stamp || "auto"
      });
    } catch {
      // Falha de rede deixa a flag não-persistida — modal reabre na
      // próxima sessão. Aceitável (UX silenciosa, não bloqueia).
    }
  }
}
flarum.reg.add('ramon-verified', 'forum/components/VerifiedCelebrationModal', VerifiedCelebrationModal);