import app from "flarum/forum/app";
import Modal from "flarum/common/components/Modal";
import Button from "flarum/common/components/Button";
import getBadgeSvg from "../../common/utils/getBadgeSvg";

/**
 * Mostrado pós-signup quando o usuário marcou o checkbox de verificação no
 * cadastro **e o admin não exige documento**. Quando documento é exigido,
 * o fluxo abre o `RequestVerificationModal` (formulário completo) em vez
 * deste — esta modal só serve para o caso "POST vazio bem-sucedido".
 */
export default class SignupVerificationConfirmationModal extends Modal {
  className() {
    return "VerifiedRequestModal VerifiedSignupConfirmationModal Modal--medium";
  }
  title() {
    return app.translator.trans("ramon-verified.forum.signup_confirmation.title");
  }
  content() {
    return m("div", {
      className: "Modal-body VerifiedRequestModal-body"
    }, m("div", {
      className: "VerifiedRequestModal-hero"
    }, m("div", {
      className: "VerifiedRequestModal-hero-icon",
      "aria-hidden": "true"
    }, m("span", {
      className: "VerifiedRequestModal-hero-iconBadge"
    }, m.trust(getBadgeSvg()))), m("h2", {
      className: "VerifiedRequestModal-hero-title"
    }, app.translator.trans("ramon-verified.forum.signup_confirmation.title")), m("p", {
      className: "VerifiedRequestModal-hero-text"
    }, app.translator.trans("ramon-verified.forum.signup_confirmation.body"))), m("div", {
      className: "VerifiedRequestModal-footer VerifiedSignupConfirmationModal-actions"
    }, m(Button, {
      className: "Button Button--primary",
      onclick: () => this.hide()
    }, app.translator.trans("ramon-verified.forum.signup_confirmation.ok_button"))));
  }
}
flarum.reg.add('ramon-verified', 'forum/components/SignupVerificationConfirmationModal', SignupVerificationConfirmationModal);